actions.script:
def _valid = ['metrics','trend','payments','forecast','recent']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }
ec.user.setPreference('SALES_DASH_ORDER', _clean.join(','))
if (context.sizes != null) {
    def _sz = ((context.sizes ?: '').toString().split(',') as List)
            .collect { it.split(':') as List }
            .findAll { it.size()==2 && _valid.contains(it[0]) && it[1]=='half' }
            .collect { it[0]+':half' }
    ec.user.setPreference('SALES_DASH_SIZE', _sz.join(','))
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def now = ec.user.nowTimestamp
def todayStr = sdf.format(now)
if (!dashDate) dashDate = ''
if (!dashDateTo) dashDateTo = ''
try {
    [dashDate,dashDateTo].findAll { it }.each { java.time.LocalDate.parse(it.toString()) }
} catch (java.time.format.DateTimeParseException ignored) {
    ec.message.addMessage('Enter a valid date range (YYYY-MM-DD). Showing all time.')
    dashDate = ''; dashDateTo = ''
}
dayStart = null; dayEndExcl = null
if (dashDate) {
    if (!dashDateTo) dashDateTo = dashDate
    if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
    dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
    dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
}
def _cw = java.util.Calendar.getInstance(); _cw.setTime(now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def weekStartStr = sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def monthStartStr = sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(); _c30.setTime(now); _c30.add(java.util.Calendar.DAY_OF_MONTH,-29); def last30Str = sdf.format(_c30.getTime())
urlAll = "?"; urlToday = "?dashDate="+todayStr+"&dashDateTo="+todayStr
urlWeek = "?dashDate="+weekStartStr+"&dashDateTo="+todayStr
urlMonth = "?dashDate="+monthStartStr+"&dashDateTo="+todayStr
url30 = "?dashDate="+last30Str+"&dashDateTo="+todayStr
presetActive = 'all'
if (dashDate) {
    presetActive = 'custom'
    if (dashDateTo == todayStr) {
        if (dashDate == todayStr) presetActive='today'
        else if (dashDate == weekStartStr) presetActive='week'
        else if (dashDate == monthStartStr) presetActive='month'
        else if (dashDate == last30Str) presetActive='last30'
    }
}
// ZE-DATEWISE: This Year preset + "Date-wise" custom-range tab (self-contained; var-name-agnostic)
def _dwSdf = new java.text.SimpleDateFormat("yyyy-MM-dd"); def _dwNow = ec.user.nowTimestamp; def _dwToday = _dwSdf.format(_dwNow)
def _dwYc = java.util.Calendar.getInstance(); _dwYc.setTime(_dwNow); _dwYc.set(java.util.Calendar.MONTH,0); _dwYc.set(java.util.Calendar.DAY_OF_MONTH,1); def _dwYearStart = _dwSdf.format(_dwYc.getTime())
urlYear = "?dashDate="+_dwYearStart+"&dashDateTo="+_dwToday
if (dashDate && dashDateTo == _dwToday && dashDate == _dwYearStart) presetActive = 'year'
showCustom = (((dateMode ?: '') == 'custom') || (presetActive == 'custom'))
urlCustom = dashDate ? ("?dateMode=custom&dashDate="+dashDate+"&dashDateTo="+dashDateTo) : "?dateMode=custom"
rangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + " – " + dashDateTo)) : "All time"

import org.moqui.entity.EntityCondition
if (dayStart || _activeShop) {
    def _q = ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId", orgId).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"])
    if (dayStart) _q.condition("invoiceDate", EntityCondition.GREATER_THAN_EQUAL_TO, dayStart).condition("invoiceDate", EntityCondition.LESS_THAN, dayEndExcl)
    if (_activeShop) _q.condition("facilityId", _activeShop)   // ZE-SHOP
    def _inv = _q.selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount").list()
    totalSalesAmount = 0.0G; _inv.each { totalSalesAmount += ((it.totalTaxableAmount ?: 0G) + (it.totalTaxAmount ?: 0G) + (it.roundOffAmount ?: 0G)) }
}

def pts = (fcRows ?: [])
if (pts.size() > 7) pts = pts.subList(0, 7)
def fcLabels = []; def fcVals = []
java.math.BigDecimal fcSumBd = java.math.BigDecimal.ZERO
double peakD = -1.0; def peakDow = null
long confSum = 0; long confN = 0
for (r in pts) {
    def ld = r.periodDate.toLocalDate()
    def dn = ld.getDayOfWeek().toString(); dn = dn.substring(0,1) + dn.substring(1,3).toLowerCase()
    fcLabels.add("'" + dn + " " + ld.getDayOfMonth() + "'")
    java.math.BigDecimal pv = (r.predictedAmount ?: java.math.BigDecimal.ZERO) as java.math.BigDecimal
    fcVals.add(pv.setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
    fcSumBd = fcSumBd.add(pv)
    double pvd = pv.doubleValue()
    if (pvd > peakD) { peakD = pvd; peakDow = ld.getDayOfWeek() }
    if (r.confidencePct != null) { confSum += (r.confidencePct as long); confN++ }
}
fcLabelsJson = "[" + fcLabels.join(",") + "]"
fcValsJson = "[" + fcVals.join(",") + "]"
fcHasData = (fcVals.size() > 0)
fcNext7 = fcSumBd.setScale(0, java.math.RoundingMode.HALF_UP)
if (peakDow != null) { def pd = peakDow.toString(); fcPeakDay = pd.substring(0,1) + pd.substring(1).toLowerCase() } else { fcPeakDay = "—" }
fcConfPct = (confN > 0) ? ((long) Math.round((double) confSum / (double) confN)) : null
fcConfWord = (fcConfPct == null) ? "Building up" : ((fcConfPct >= 75) ? "Strong" : ((fcConfPct >= 60) ? "Good" : ((fcConfPct >= 45) ? "Fair" : "Early estimate")))

import org.moqui.entity.EntityCondition
import java.util.Calendar
def nowTs = ec.user.nowTimestamp
def revArr = []; def ordArr = []
// ZE-DASH: per-metric 6-month sparklines (mockup stat-card mini-bars), computed in the same loop
def _spQ = []; def _spC = []; def _spI = []
for (int i = 5; i >= 0; i--) {
    def c = Calendar.getInstance(); c.setTimeInMillis(nowTs.getTime()); c.add(Calendar.MONTH, -i)
    c.set(Calendar.DAY_OF_MONTH,1); c.set(Calendar.HOUR_OF_DAY,0); c.set(Calendar.MINUTE,0); c.set(Calendar.SECOND,0); c.set(Calendar.MILLISECOND,0)
    def start = new java.sql.Timestamp(c.getTimeInMillis())
    def c2 = (Calendar) c.clone(); c2.add(Calendar.MONTH,1)
    def end = new java.sql.Timestamp(c2.getTimeInMillis())
    def _mq = ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId", orgId).condition("invoiceTypeEnumId", "InvoiceSales").condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"]).condition("invoiceDate", EntityCondition.GREATER_THAN_EQUAL_TO, start).condition("invoiceDate", EntityCondition.LESS_THAN, end)
    if (_activeShop) _mq.condition("facilityId", _activeShop)   // ZE-SHOP
    def invs = _mq.selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount").list()
    def rev = 0.0G; invs.each { rev += ((it.totalTaxableAmount ?: 0G) + (it.totalTaxAmount ?: 0G) + (it.roundOffAmount ?: 0G)) }
    revArr.add(rev.setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
    ordArr.add(invs.size())
    _spQ.add(ec.entity.find("mantle.order.OrderHeaderAndPart").condition("orderId",EntityCondition.NOT_IN,_mixedOrders.mixedOrderIds ?: ['__NO_MIXED_SALES_ORDER__']).condition("statusId","OrderProposed").condition("vendorPartyId",orgId).condition("entryDate",EntityCondition.GREATER_THAN_EQUAL_TO,start).condition("entryDate",EntityCondition.LESS_THAN,end).count())
    _spI.add(ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId",orgId).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId",EntityCondition.NOT_EQUAL,"InvoiceCancelled").condition("invoiceDate",EntityCondition.GREATER_THAN_EQUAL_TO,start).condition("invoiceDate",EntityCondition.LESS_THAN,end).count())
    try { _spC.add(ec.entity.find("mantle.party.PartyDetailAndRole").condition("roleTypeId","Customer").condition("ownerPartyId",orgId).condition("createdDate",EntityCondition.GREATER_THAN_EQUAL_TO,start).condition("createdDate",EntityCondition.LESS_THAN,end).count()) } catch (Exception _e) { _spC.add(0) }
}
salesRevJson = "[" + revArr.join(",") + "]"
salesOrdJson = "[" + ordArr.join(",") + "]"
salesSpark = salesRevJson
quotesSpark = "[" + _spQ.join(",") + "]"
custSpark = "[" + _spC.join(",") + "]"
invSpark = "[" + _spI.join(",") + "]"
long onCredit = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", orgId).condition("statusId","PtCompleted").condition("isCredit","Y").count()
long totalSalesCnt = 0
for (r in salesSums) { totalSalesCnt += ((r.cnt ?: 0) as long) }
long paidCnt = totalSalesCnt - onCredit
if (paidCnt < 0) paidCnt = 0
salesStatusJson = "[" + paidCnt + "," + onCredit + "]"
// ZE-DASH layout: switchable widgets (+ cashier role default) + saved drag order
def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'forecast,payments'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('SALES_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showMetrics = !_hiddenSet.contains('metrics'); showTrend = !_hiddenSet.contains('trend'); showPayments = !_hiddenSet.contains('payments')
showForecast = !_hiddenSet.contains('forecast'); showRecent = !_hiddenSet.contains('recent')
w_metrics = showMetrics ? 'Y' : ''; w_trend = showTrend ? 'Y' : ''; w_payments = showPayments ? 'Y' : ''
w_forecast = showForecast ? 'Y' : ''; w_recent = showRecent ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('SALES_DASH_ORDER') ?: '')
dashSizeCsv = (ec.user.getPreference('SALES_DASH_SIZE') ?: '')
urlSettings = dashDate ? ("?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1") : "?showSettings=1"

import org.moqui.entity.EntityCondition
import java.util.Calendar
salesDelta = null; quotesDelta = null; invoicesDelta = null; customersDelta = null
catNamesJson = "[]"; catValsJson = "[]"; catHasData = false
if (orgId) {
    def _now2 = ec.user.nowTimestamp
    def _tsShift = { days -> def c = Calendar.getInstance(); c.setTimeInMillis(_now2.getTime()); c.set(Calendar.HOUR_OF_DAY,0); c.set(Calendar.MINUTE,0); c.set(Calendar.SECOND,0); c.set(Calendar.MILLISECOND,0); c.add(Calendar.DAY_OF_MONTH, days); return new java.sql.Timestamp(c.getTimeInMillis()) }
    def _d0 = _tsShift(1); def _d30 = _tsShift(-30); def _d60 = _tsShift(-60)
    def _pct = { cur, prev -> (prev == null || (prev as BigDecimal) == 0G) ? null : ((((cur as BigDecimal) - (prev as BigDecimal)) * 100G) / (prev as BigDecimal)).setScale(1, java.math.RoundingMode.HALF_UP) }
    def _salesSum = { from, to -> def s = 0.0G; ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId", orgId).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"]).condition("invoiceDate", EntityCondition.GREATER_THAN_EQUAL_TO, from).condition("invoiceDate", EntityCondition.LESS_THAN, to).selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount").list().each { s += ((it.totalTaxableAmount?:0G)+(it.totalTaxAmount?:0G)+(it.roundOffAmount?:0G)) }; return s }
    def _qCnt = { from, to -> ec.entity.find("mantle.order.OrderHeaderAndPart").condition("orderId",EntityCondition.NOT_IN,_mixedOrders.mixedOrderIds ?: ['__NO_MIXED_SALES_ORDER__']).condition("statusId","OrderProposed").condition("vendorPartyId",orgId).condition("entryDate",EntityCondition.GREATER_THAN_EQUAL_TO,from).condition("entryDate",EntityCondition.LESS_THAN,to).count() }
    def _iCnt = { from, to -> ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId",orgId).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId",EntityCondition.NOT_EQUAL,"InvoiceCancelled").condition("invoiceDate",EntityCondition.GREATER_THAN_EQUAL_TO,from).condition("invoiceDate",EntityCondition.LESS_THAN,to).count() }
    def _cCnt = { from, to -> try { return ec.entity.find("mantle.party.PartyDetailAndRole").condition("roleTypeId","Customer").condition("ownerPartyId",orgId).condition("createdDate",EntityCondition.GREATER_THAN_EQUAL_TO,from).condition("createdDate",EntityCondition.LESS_THAN,to).count() } catch (Exception _e) { return null } }
    salesDelta = _pct(_salesSum(_d30,_d0), _salesSum(_d60,_d30))
    quotesDelta = _pct(_qCnt(_d30,_d0), _qCnt(_d60,_d30))
    invoicesDelta = _pct(_iCnt(_d30,_d0), _iCnt(_d60,_d30))
    def _cc30 = _cCnt(_d30,_d0); def _cc60 = _cCnt(_d60,_d30)
    customersDelta = (_cc30 == null || _cc60 == null) ? null : _pct(_cc30, _cc60)

    def _catFrom = dayStart ?: _tsShift(-90)
    def _catTo = dayEndExcl ?: _d0
    def _catMap = [:]
    ec.entity.find("zenith.erp.sales.InvoiceCategorySalesView").condition("fromPartyId",orgId).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId",EntityCondition.NOT_EQUAL,"InvoiceCancelled").condition("invoiceDate",EntityCondition.GREATER_THAN_EQUAL_TO,_catFrom).condition("invoiceDate",EntityCondition.LESS_THAN,_catTo).selectField("productCategoryId").selectField("taxableAmount").selectField("totalTaxAmount").list().each { r ->
        def cid = r.productCategoryId
        if (cid) _catMap[cid] = ((_catMap[cid] ?: 0.0G)) + ((r.taxableAmount ?: 0G) + (r.totalTaxAmount ?: 0G))
    }
    def _catTop = _catMap.entrySet().toList().sort { -it.value }.take(6)
    def _cn = []; def _cv = []
    _catTop.each { e ->
        def pc = ec.entity.find("mantle.product.category.ProductCategory").condition("productCategoryId", e.key).selectField("categoryName").one()
        _cn.add((pc?.categoryName ?: e.key).toString())
        _cv.add((e.value as BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
    }
    // The chart JSON is inserted into an HTML onload attribute. Encode both JS strings
    // and the surrounding HTML attribute so category names cannot break chart rendering.
    catNamesJson = groovy.json.JsonOutput.toJson(_cn).replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;").replace(">", "&gt;")
    catValsJson = "[" + _cv.join(",") + "]"
    catHasData = (_cv.size() > 0)
}
// stat-card delta chip + sparkline (inline HTML, no chart lib) for each metric
def _deltaHtml = { d ->
    if (d == null) return '<div style="margin-top:8px;font-size:11px;color:#9a9aa8;">&mdash; no prior data</div>'
    def up = ((d as BigDecimal) >= 0G)
    return '<div style="margin-top:8px;font-size:11.5px;font-weight:700;color:' + (up ? '#0E9F6E' : '#DC2626') + ';">' + (up ? '&#8593;' : '&#8595;') + ' ' + (d.abs().toPlainString()) + '% <span style="color:#9a9aa8;font-weight:500;">vs last 30 days</span></div>'
}
def _sparkHtml = { arrStr, col ->
    def vals = []
    try { (arrStr ?: '').replaceAll('[\\[\\]]','').split(',').each { if (it?.trim()) vals.add(new BigDecimal(it.trim())) } } catch (Exception _e) {}
    if (vals.size() < 2) return ''
    def mx = vals.max(); if (mx == null || mx == 0G) return ''
    def b = new StringBuilder('<div style="display:flex;align-items:flex-end;gap:2px;height:26px;">')
    vals.each { v -> def h = ((v * 100G) / mx).setScale(0, java.math.RoundingMode.HALF_UP); b.append('<div style="width:5px;height:' + h + '%;min-height:2px;background:' + col + ';border-radius:2px 2px 0 0;opacity:.85;"></div>') }
    b.append('</div>'); return b.toString()
}
salesDeltaHtml = _deltaHtml(salesDelta); salesSparkHtml = _sparkHtml(salesSpark ?: '', '#0E9F6E')
quotesDeltaHtml = _deltaHtml(quotesDelta); quotesSparkHtml = _sparkHtml(quotesSpark ?: '', '#D97706')
custDeltaHtml = _deltaHtml(customersDelta); custSparkHtml = _sparkHtml(custSpark ?: '', '#2563EB')
invDeltaHtml = _deltaHtml(invoicesDelta); invSparkHtml = _sparkHtml(invSpark ?: '', '#DC2626')
